fn main() {
    var m: Map[String, int] = [:]
    m.set("a".toString(), 1)
    m.update("a".toString(), 0, (n) => n + 1)
    if let p = m.getMut("a") { *p += 3 }
    println(m.getCopy("a") ?? 0)
    let removed = m.remove("a") ?? 0
    println("${removed} ${m.len()}")
    var s = Set[int]{}
    s.add(1)
    s.add(1)
    let before = s.len()
    let found = s.has(1)
    let erased = s.remove(1)
    println("${before} ${found} ${erased} ${s.len()}")
    var fs: Vec[f64] = [2.0, 1.0]
    fs.sortBy((a, b) => a.totalCmp(b) == .Less)
    println("${fs[0]:.1}")
    var out = String{}
    out.push("x")
    let parts = "a,b".split(",")
    out.push(parts.join("|"))
    println(out)
    let pair = (1, "ok".toString())
    println("${pair.0} ${pair.1}")
}

enum Issue { Bad }
fn parse(s: str) -> int ! Issue {
    let n = s.parseInt() ?? return err(.Bad)
    return n
}
fn load(s: str) -> int ! Issue {
    let n = try parse(s)
    return n + 1
}
fn main() {
    match load("41") {
        ok(n) => println(n)
        err(_e) => println("bad")
    }
    let fallback = parse("x") catch _ => 0
    println(fallback)
    var opt: ?String = some("owned".toString())
    match take(&opt) {
        some(value) => println(value)
        none => println("missing")
    }
    println(opt.isNone())
}

fn mark(label: str, value: int) -> int {
    println(label)
    return value
}
fn main() {
    var v = [0]
    v[mark("index", 0)] = mark("value", 9)
    v[mark("index+", 0)] += mark("value+", 2)
    println(v[0])
}

